  "Day 5 Blastocyst": { hi: "डे 5 ब्लास्टोसिस्ट", gu: "ડે 5 બ્લાસ્ટોસિસ્ટ" },
  "Day 3 Cleavage": { hi: "डे 3 क्लीवेज", gu: "ડે 3 ક્લીવેજ" },
