  "Low probability of getting pregnant": { hi: "गर्भवती होने की संभावना कम है", gu: "ગર્ભવતી થવાની શક્યતા ઓછી છે" },
  "There is a chance of getting pregnant": { hi: "गर्भवती होने की संभावना है", gu: "ગર્ભવતી થવાની શક્યતા છે" },
  "High probability of getting pregnant": { hi: "गर्भवती होने की संभावना अधिक है", gu: "ગર્ભવતી થવાની શક્યતા વધારે છે" },

